def eprint(s: str):
    sys.stderr.write(s)
    if not s.endswith('\n'):
        sys.stderr.write('\n')


def exit_err(msg: str, usage: str | None = None, hint_arg: str | None = None, bare_usage: bool = False):
    sys.stderr.write(f"error: {msg}\n")
    if hint_arg is not None:
        sys.stderr.write(f"\n\tIf you tried to supply `{hint_arg}` as a value rather than a flag, use `-- {hint_arg}`\n")
    if usage is not None:
        if bare_usage:
            sys.stderr.write(f"\n{usage}\n")
        else:
            sys.stderr.write(f"\nUSAGE:\n    {usage}\n")
    sys.stderr.write("\nFor more information try --help\n")
    raise SystemExit(2)


def unexpected(arg: str, usage: str | None = None):
    if usage is None:
        usage = f"{progname()} [OPTIONS]"
    hint = arg if arg.startswith('-') else None
    exit_err(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context", usage, hint)


def value_label(longname: str) -> str:
    short = LONG_TO_SHORT[longname]
    return f"--{longname} <{OPT_LONG[short][1]}>"


def duplicate(longname: str):
    exit_err(f"The argument '{value_label(longname)}' was provided more than once, but cannot be used multiple times", f"{progname()} [OPTIONS]")


def missing(longname: str):
    exit_err(f"The argument '{value_label(longname)}' requires a value but none was supplied", f"{progname()} [OPTIONS]")


def invalid_int(longname: str, value: str):
    if value == '':
        why = 'cannot parse integer from empty string'
    elif value.isdigit() and int(value) > (2**64 - 1):
        why = 'number too large to fit in target type'
    else:
        why = 'invalid digit found in string'
    exit_err(f"Invalid value \"{value}\" for '{value_label(longname)}': {why}", None)


def parse_int(longname: str, value: str) -> int:
    if not value.isdigit():
        invalid_int(longname, value)
    try:
        n = int(value)
    except Exception:
        invalid_int(longname, value)
    if n > 2**64 - 1:
        invalid_int(longname, value)
    return n


def set_option(opts: Options, seen: set, longname: str, value: str):
    if longname in seen:
        duplicate(longname)
    seen.add(longname)
    if longname == 'number-of-words':
        opts.number_of_words = parse_int(longname, value)
    elif longname == 'number-of-secs':
        opts.number_of_secs = parse_int(longname, value)
    elif longname == 'full-sentences':
        opts.full_sentences = parse_int(longname, value)
    elif longname == 'prompt':
        opts.prompt = value
    elif longname == 'supported-language':
        if value not in ('english', 'english1k', 'english10k'):
            exit_err(f"\"{value}\" isn't a valid value for '--supported-language <SUPPORTED_LANGUAGE>'\n\t[possible values: english, english1k, english10k]", f"{progname()} --supported-language <SUPPORTED_LANGUAGE>")
        opts.supported_language = value


def parse_args(argv: list[str]) -> Options:
    opts = Options()
    seen: set[str] = set()
    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == '--':
            i += 1
            while i < len(argv):
                unexpected(argv[i])
            break
        if tok in ('-h', '--help'):
            print(help_text(progname()))
            raise SystemExit(0)
        if tok in ('-V', '--version'):
            print(VERSION)
            raise SystemExit(0)
        if tok.startswith('--help='):
            exit_err(f"The value '{tok[len('--help'):]}' was provided to '--help' but it wasn't expecting any more values", f"{progname()} [OPTIONS]", bare_usage=True)
        if tok.startswith('--version='):
            exit_err(f"The value '{tok[len('--version'):]}' was provided to '--version' but it wasn't expecting any more values", f"{progname()} [OPTIONS]", bare_usage=True)
        if tok.startswith('--'):
            body = tok[2:]
            if '=' in body:
                name, val = body.split('=', 1)
                if name in LONG_TO_SHORT:
                    set_option(opts, seen, name, val)
                    i += 1
                    continue
                else:
                    unexpected(tok)
            if body in LONG_TO_SHORT:
                longname = body
                if i + 1 >= len(argv):
                    missing(longname)
                nxt = argv[i+1]
                if nxt.startswith('-'):
                    unexpected(nxt, f"{progname()} --{longname} <{OPT_LONG[LONG_TO_SHORT[longname]][1]}>" if nxt.startswith('--') else None)
                set_option(opts, seen, longname, nxt)
                i += 2
                continue
            unexpected(tok)
        elif tok.startswith('-') and tok != '-':
            if len(tok) == 2:
                c = tok[1]
                if c in OPT_LONG:
                    longname = OPT_LONG[c][0]
                    if i + 1 >= len(argv):
                        missing(longname)
                    nxt = argv[i+1]
                    if nxt.startswith('-'):
                        # clap reports the following flag, not a missing value
                        usage = f"{progname()} --{longname} <{OPT_LONG[c][1]}>" if nxt.startswith('--') else None
                        unexpected(nxt, usage)
                    set_option(opts, seen, longname, nxt)
                    i += 2
                    continue
                unexpected(tok)
            else:
                c = tok[1]
                if c in ('h', 'V'):
                    unexpected(tok)
                if c in OPT_LONG:
                    longname = OPT_LONG[c][0]
                    val = tok[2:]
                    set_option(opts, seen, longname, val)
                    i += 1
                    continue
                unexpected(tok)
        else:
            unexpected(tok)
    return opts


def language_words(lang: str) -> list[str]:
    if lang == 'english':
        return ENGLISH
    if lang == 'english1k':
        return ENGLISH + EXTRA_1K
    return ENGLISH + EXTRA_1K + EXTRA_10K


def make_prompt(opts: Options, force_generated: bool = False) -> str:
    if opts.prompt is not None and not force_generated:
        return opts.prompt
    if opts.full_sentences is not None:
        parts = []
        for _ in range(opts.full_sentences):
            if random.random() < 0.5:
                s = f"The {random.choice(ADJ)} {random.choice(ADJ)} {random.choice(NOUN)} {random.choice(VERB)} {random.choice(ADV)} {random.choice(ADV)} the {random.choice(ADJ)} {random.choice(NOUN)}."
            else:
                s = f"The {random.choice(ADJ)} {random.choice(NOUN)} {random.choice(ADV)} {random.choice(ADV)} {random.choice(VERB)}."
            parts.append(s)
        return ' '.join(parts)
    words = language_words(opts.supported_language)
    return ' '.join(random.choice(words) for _ in range(opts.number_of_words))


def fmt_date():
    # GNU strftime supports %e and matches the observed two-space single digit day.
    try:
        return time.strftime('%a %b %e %H:%M:%S %Y')
    except Exception:
        t = time.localtime()
        return time.strftime('%a %b ', t) + f"{t.tm_mday:2d}" + time.strftime(' %H:%M:%S %Y', t)


def log_path():
    base = os.environ.get('XDG_CONFIG_HOME') or os.path.join(os.path.expanduser('~'), '.config')
    return os.path.join(base, 'thokr', 'log.csv')


def append_log(opts: Options, elapsed: float, wpm_s: str, acc: int, sd: float):
    path = log_path()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    exists = os.path.exists(path) and os.path.getsize(path) > 0
    with open(path, 'a', encoding='utf-8') as f:
        if not exists:
            f.write('date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev\n')
        secs = '' if opts.number_of_secs is None else f"{float(opts.number_of_secs):.2f}"
        f.write(f"{fmt_date()},{opts.number_of_words},{secs},{elapsed:.2f},{wpm_s},{acc},{sd:.2f}\n")


def correct_count(prompt: str, typed: list[str]) -> int:
    return sum(1 for i, ch in enumerate(typed[:len(prompt)]) if i < len(prompt) and ch == prompt[i])


def calc_metrics(prompt: str, typed: list[str], elapsed: float):
    total_typed = len(typed)
    corr = correct_count(prompt, typed)
    acc = int(round((corr / total_typed) * 100)) if total_typed else 0
    if elapsed <= 0.005 and corr > 0:
        wpm_s = 'inf'
        wpm_val = math.inf
    else:
        denom = max(1, math.ceil(max(elapsed, 0.0)))
        wpm_val = (corr / 5.0) * 60.0 / denom
        wpm_s = str(int(round(wpm_val)))
    return wpm_s, wpm_val, acc, 0.0


def strip_len(s: str) -> int:
    return len(s)


def styled_prompt(prompt: str, typed: list[str], start_idx: int, count: int) -> str:
    out = []
    for pos in range(start_idx, start_idx + count):
        ch = prompt[pos]
        if pos < len(typed):
            if typed[pos] == ch:
                out.append('\x1b[1m\x1b[38;5;2m' + ch)
            else:
                out.append('\x1b[1m\x1b[38;5;1m' + ch)
        elif pos == len(typed):
            out.append('\x1b[1;2;4m' + ch)
        else:
            out.append('\x1b[0;1;2m\x1b[39m\x1b[49m' + ch)
    out.append('\x1b[0m\x1b[39m\x1b[49m')
    return ''.join(out)


def wrap_prompt(prompt: str, width: int):
    if prompt == '':
        return ['']
    limit = max(10, width - 10)
    lines = []
    idx = 0
    for para in prompt.split('\n'):
        if para == '':
            lines.append((idx, 0, ''))
            idx += 1
            continue
        # Greedy word wrapping while preserving indices into prompt.
        line_start = idx
        line_len = 0
        word_start = idx
        words = para.split(' ')
        for wi, word in enumerate(words):
            add = len(word) if line_len == 0 else len(word) + 1
            if line_len and line_len + add > limit:
                lines.append((line_start, line_len, prompt[line_start:line_start+line_len]))
                line_start = word_start
                line_len = len(word)
            else:
                line_len += add
            word_start += len(word)
            if wi != len(words) - 1:
                word_start += 1
        if line_len or not words:
            lines.append((line_start, line_len, prompt[line_start:line_start+line_len]))
        idx += len(para) + 1
    return lines


def write_at(buf: list[str], row: int, col: int, text: str):
    if row < 1:
        row = 1
    if col < 1:
        col = 1
    buf.append(f"\x1b[{row};{col}H{text}")


def render_test(prompt: str, typed: list[str], opts: Options, app_start: float, first_key: float | None):
    width, height = shutil.get_terminal_size((80, 24))
    lines = wrap_prompt(prompt, width)
    start_row = max(1, height // 2 - len(lines) // 2 + 1)
    buf = ['\x1b[?25l', '\x1b[2J\x1b[H']
    if opts.number_of_secs is not None:
        remaining = max(0.0, float(opts.number_of_secs) - (time.monotonic() - app_start))
        timer = f"\x1b[1;2m{remaining:.1f}\x1b[0m\x1b[39m\x1b[49m"
        write_at(buf, max(1, start_row - 2), max(1, (width - len(f'{remaining:.1f}')) // 2 + 1), timer)
    for li, item in enumerate(lines):
        if isinstance(item, tuple):
            idx, ln, plain = item
        else:
            idx, ln, plain = 0, len(item), item
        col = max(1, (width - ln) // 2 + 1)
        text = styled_prompt(prompt, typed, idx, ln) if ln else ''
        write_at(buf, start_row + li, col, text)
    sys.stdout.write(''.join(buf))
    sys.stdout.flush()


def render_result(wpm_s: str, wpm_val: float, acc: int, sd: float, elapsed: float):
    width, height = shutil.get_terminal_size((80, 24))
    graph_w = max(20, width - 14)
    left = 5
    top = 3
    graph_h = min(14, max(6, height - 10))
    axis_max = max(1, math.ceil(max(elapsed, 0.0)))
    top_label = wpm_s
    if wpm_s != 'inf':
        try:
            top_label = str(max(0, int(wpm_s)))
        except Exception:
            pass
    buf = ['\x1b[?25l', '\x1b[2J\x1b[H']
    # Top row with vertical axis and wpm label.
    write_at(buf, top, left, f"\x1b[1m{top_label}\x1b[0m\x1b[39m\x1b[49m┬wpm")
    axis_col = left + max(len(top_label), 1)
    for r in range(1, graph_h):
        write_at(buf, top + r, axis_col, '│')
    write_at(buf, top + graph_h, left, f"\x1b[1m0\x1b[0m\x1b[39m\x1b[49m" + ' ' * max(0, axis_col-left-1) + '└' + '─' * graph_w)
    write_at(buf, top + graph_h, min(width-7, axis_col + graph_w - 7), 'seconds')
    write_at(buf, top + graph_h + 1, axis_col, f"\x1b[1m1\x1b[0m\x1b[39m\x1b[49m")
    right = f"\x1b[1m{axis_max:.2f}\x1b[0m\x1b[39m\x1b[49m"
    write_at(buf, top + graph_h + 1, max(1, axis_col + graph_w - len(f'{axis_max:.2f}') + 1), right)
    metrics = f"{wpm_s} wpm   {acc}% acc   {sd:.2f} sd"
    write_at(buf, min(height, top + graph_h + 3), max(1, (width - len(metrics)) // 2 + 1), f"\x1b[1m{metrics}\x1b[0m\x1b[39m\x1b[49m")
    write_at(buf, min(height, top + graph_h + 5), left, "\x1b[3m(r)etry / (n)ew / (esc)ape\x1b[0m\x1b[39m\x1b[49m")
    sys.stdout.write(''.join(buf))
    sys.stdout.flush()


def read_key(fd: int, timeout: float):
    r, _, _ = select.select([fd], [], [], timeout)
    if not r:
        return None
    data = os.read(fd, 32)
    if not data:
        return None
    # Decode common terminal escape sequences.
    if data in (b'\x1b',):
        return 'ESC'
    if data.startswith(b'\x1b['):
        if data.endswith(b'D'):
            return 'LEFT'
        if data.endswith(b'C'):
            return 'RIGHT'
        return None
    if data in (b'\x03',):
        return 'CTRL_C'
    if data in (b'\x7f', b'\x08'):
        return 'BACKSPACE'
    try:
        return data.decode('utf-8', errors='ignore')
    except Exception:
        return None


def run_tui(opts: Options):
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    prompt = make_prompt(opts)
    force_generated = False
    typed: list[str] = []
    app_start = time.monotonic()
    first_key: float | None = None
    finish_time: float | None = None
    state = 'test'
    logged = False
    last_render = 0.0
    metrics = ('0', 0.0, 0, 0.0)

    def reset(new_prompt: bool = False):
        nonlocal prompt, force_generated, typed, app_start, first_key, finish_time, state, logged, metrics
        if new_prompt:
            force_generated = True
            prompt = make_prompt(opts, force_generated=True)
        typed = []
        app_start = time.monotonic()
        first_key = None
        finish_time = None
        state = 'test'
        logged = False
        metrics = ('0', 0.0, 0, 0.0)

    def finish():
        nonlocal state, finish_time, metrics, logged
        if state == 'result':
            return
        finish_time = time.monotonic()
        elapsed = 0.0 if first_key is None else max(0.0, finish_time - first_key)
        metrics = calc_metrics(prompt, typed, elapsed)
        state = 'result'
        if len(typed) > 0 and not logged:
            append_log(opts, elapsed, metrics[0], metrics[2], metrics[3])
            logged = True
        render_result(metrics[0], metrics[1], metrics[2], metrics[3], elapsed)

    try:
        tty.setraw(fd)
        sys.stdout.write('\x1b[?1049h\x1b[39m\x1b[49m\x1b[0m\x1b[?25l')
        sys.stdout.flush()
        # Empty prompts/zero-length generated tests display the result immediately, without logging.
        if len(prompt) == 0:
            state = 'result'
            metrics = calc_metrics(prompt, typed, 0.0)
            render_result(metrics[0], metrics[1], metrics[2], metrics[3], 0.0)
        else:
            render_test(prompt, typed, opts, app_start, first_key)
            last_render = time.monotonic()
        while True:
            now = time.monotonic()
            if state == 'test' and opts.number_of_secs is not None and (now - app_start) >= opts.number_of_secs:
                finish()
                continue
            key = read_key(fd, 0.05)
            if key is None:
                if state == 'test' and opts.number_of_secs is not None and now - last_render > 0.1:
                    render_test(prompt, typed, opts, app_start, first_key)
                    last_render = now
                continue
            if key in ('CTRL_C', 'ESC'):
                break
            if state == 'result':
                if key and isinstance(key, str):
                    low = key.lower()[:1]
                    if low == 'r':
                        reset(new_prompt=False)
                        render_test(prompt, typed, opts, app_start, first_key)
                    elif low == 'n':
                        reset(new_prompt=True)
                        render_test(prompt, typed, opts, app_start, first_key)
                continue
            # state == test
            if key == 'LEFT':
                reset(new_prompt=False)
                render_test(prompt, typed, opts, app_start, first_key)
                continue
            if key == 'RIGHT':
                reset(new_prompt=True)
                render_test(prompt, typed, opts, app_start, first_key)
                continue
            if key == 'BACKSPACE':
                if typed:
                    typed.pop()
                    if not typed:
                        first_key = None
                render_test(prompt, typed, opts, app_start, first_key)
                continue
            # Printable text may include multiple bytes/chars (tmux send-keys can deliver chunks).
            for ch in key:
                if ch == '\r':
                    ch = '\n'
                if ch < ' ' and ch != '\n':
                    continue
                if len(typed) < len(prompt):
                    if first_key is None:
                        first_key = time.monotonic()
                    typed.append(ch)
                    if len(typed) >= len(prompt):
                        finish()
                        break
            if state == 'test':
                render_test(prompt, typed, opts, app_start, first_key)
                last_render = time.monotonic()
    finally:
        try:
            termios.tcsetattr(fd, termios.TCSADRAIN, old)
        except Exception:
            pass
        sys.stdout.write('\x1b[?25h\x1b[?1049l\x1b[0m\x1b[39m\x1b[49m')
        sys.stdout.flush()


def main():
    opts = parse_args(sys.argv[1:])
    if not sys.stdin.isatty():
        sys.stderr.write("error: stdin must be a tty\n\nUSAGE:\n    thokr [OPTIONS]\n\nFor more information try --help\n")
        return 2
    run_tui(opts)
    return 0

if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except BrokenPipeError:
        raise SystemExit(1)
