LONG_TO_SHORT = {v[0]: k for k, v in OPT_LONG.items()}

@dataclass
class Options:
    number_of_words: int = 15
    supported_language: str = 'english'
    prompt: str | None = None
    number_of_secs: int | None = None
    full_sentences: int | None = None


def progname():
    return os.path.basename(sys.argv[0]) or 'executable'


def help_text(prog: str) -> str:
    return f"""thokr 0.4.1
sleek typing tui with visualized results and historical logging

USAGE:
    {prog} [OPTIONS]

OPTIONS:
    -f, --full-sentences <NUMBER_OF_SENTENCES>
